def compute(vars):
    volatility_2018 = vars["v1"]
    volatility_2019 = vars["v2"]
    value = 2018 if volatility_2018 < volatility_2019 else 2019 if volatility_2019 < volatility_2018 else None
    return {
        "value": value,
        "trace": {
            "volatility_2018": volatility_2018,
            "volatility_2019": volatility_2019,
            "output_meta": {"currency": None, "scale": None, "unit": "year"}
        }
    }
